import { FC } from 'react';

type CalendarType = 'single' | 'range' | 'multiple';
interface CalendarProps {
    /** 选择类型 */
    type?: CalendarType;
    /** 当前选中值 (受控) */
    value?: Date | Date[] | [Date, Date];
    /** 默认选中值 (非受控) */
    defaultValue?: Date | Date[] | [Date, Date];
    /** 最小日期 */
    minDate?: Date;
    /** 最大日期 */
    maxDate?: Date;
    /** 是否显示 (受控) */
    open?: boolean;
    /** 是否显示（兼容旧版，建议使用 open） */
    visible?: boolean;
    /** 是否显示遮罩 */
    showMask?: boolean;
    /** 点击遮罩是否关闭 */
    closeOnOverlayClick?: boolean;
    /** 标题 */
    title?: string;
    /** 确认按钮文字 */
    confirmText?: string;
    /** 是否显示确认按钮 */
    showConfirm?: boolean;
    /** 每周第一天 (0-6, 0为周日) */
    firstDayOfWeek?: number;
    /** 选中日期变化回调 */
    onChange?: (value: Date | Date[] | [Date, Date] | undefined) => void;
    /** 确认回调 */
    onConfirm?: (value: Date | Date[] | [Date, Date]) => void;
    /** 关闭回调 */
    onClose?: () => void;
    /** 自定义类名 */
    className?: string;
}

declare const Calendar: FC<CalendarProps>;

export { Calendar, Calendar as default };
export type { CalendarProps, CalendarType };
